WITH history AS (SELECT DATE_TRUNC('DAY', "EVENT_DATE") AS period, EXTRACT(DOW FROM "EVENT_DATE") AS dow, COUNT(*) AS cnt FROM "FAKE_PROJECT"."DATASET"."ORDERS" WHERE "EVENT_DATE" >= '2026-05-01'::DATE - INTERVAL '28 DAY' AND "EVENT_DATE" < '2026-05-01'::DATE GROUP BY period, dow) SELECT dow, MIN(cnt) AS min_cnt, MAX(cnt) AS max_cnt, COUNT(*) AS n FROM history GROUP BY dow